def resolve(path, cwd, links):
    # Normalize and split the path into components
    if path.startswith('/'):
        current = '/'
        components = [c for c in path.split('/') if c and c != '.']
    else:
        current = cwd
        components = [c for c in path.split('/') if c and c != '.']

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        if comp == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            i += 1
        else:
            # Append component
            if current == '/':
                candidate = '/' + comp
            else:
                candidate = current + '/' + comp

            # Check if this path is a symlink
            if candidate in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[candidate]

                # Parse the target
                if target.startswith('/'):
                    # Absolute link target
                    current = '/'
                    target_components = [c for c in target.split('/') if c and c != '.']
                else:
                    # Relative link target - relative to the directory containing the link
                    current = candidate.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                    target_components = [c for c in target.split('/') if c and c != '.']

                # Replace remaining components with target components + rest
                components = target_components + components[i+1:]
                i = 0
            else:
                current = candidate
                i += 1

    # Return result (no trailing slash except for '/')
    return current

